pub fn rotate_left<T>(slice: &mut [T], mid: usize) {
    assert!(mid <= slice.len());
    let k = mid;
    let n = slice.len();
    if k == 0 || k == n {
        return;
    }

    slice[..k].reverse();
    slice[k..].reverse();
    slice.reverse();
}

