func caseInsensitiveCompare(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	toLower := func(c byte) byte {
		if c >= 'A' && c <= 'Z' {
			return c + 32
		}
		return c
	}
	for i := 0; i < len(a); i++ {
		if toLower(a[i]) != toLower(b[i]) {
			return false
		}
	}
	return true
}

pub fn retain<T, F>(&mut self, mut f: F)
where
    F: FnMut(&T) -> bool,
{
    let len = self.len();
    let mut del = 0;
    for i in 0..len {
        if !f(&self[i]) {
            del += 1;
        } else if del > 0 {
            self.swap(i - del, i);
        }
    }
    if del > 0 {
        self.truncate(len - del);
    }
}

pub fn retain<T, F>(&mut self, mut f: F)
where
    F: FnMut(&T) -> bool,
{
    let mut read = 0;
    let mut write = 0;
    let len = self.len();

    while read < len {
        if f(&self[read]) {
            if read != write {
                self.swap(read, write);
            }
            write += 1;
        }
        read += 1;
    }
    self.truncate(write);
}

