pub fn retain<T, F>(&mut self, mut f: F)
where
    F: FnMut(&T) -> bool,
{
    let len = self.len();
    let mut retain_idx = 0;

    for i in 0..len {
        if f(&self[i]) {
            if i != retain_idx {
                self.swap(i, retain_idx);
            }
            retain_idx += 1;
        }
    }
    self.truncate(retain_idx);
}

pub fn retain<T, F>(&mut self, mut f: F)
where
    F: FnMut(&T) -> bool,
{
    let mut deleted = 0;
    let original_len = self.len();

    for i in 0..original_len {
        if !f(&self[i]) {
            deleted += 1;
        } else if deleted > 0 {
            self.swap(i - deleted, i);
        }
    }
    self.truncate(original_len - deleted);
}

