   * @private
   * @param {Node} node
   */
  _remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  /**
   * @private
   * @param {Node} node
   */
  _addToHead(node) {
    node.next = this.head.next;
    node.next.prev = node;
    node.prev = this.head;
    this.head.next = node;
  }
}

class LRUCache {
  /**
   * @param {number} capacity
   */
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();

    // Sentinel head and tail nodes for the doubly linked list
    this.head = { key: 0, value: 0, prev: null, next: null };
    this.tail = { key: 0, value: 0, prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  /**
   * @param {number} key
   * @return {number}
   */
  get(key) {
    const node = this.map.get(key);
    if (node === undefined) {
      return -1;
    }
    this._moveToHead(node);
    return node.value;
  }

  /**
   * @param {number} key
   * @param {number} value
   * @return {void}
   */
  put(key, value) {
    const node = this.map.get(key);
    if (node !== undefined) {
      node.value = value;
      this._moveToHead(node);
    } else {
      const newNode = { key, value, prev: null, next: null };
      this.map.set(key, newNode);
      this._addNode(newNode);

      if (this.map.size > this.capacity) {
        const tailNode = this._popTail();
        this.map.delete(tailNode.key);
      }
    }
  }

  /**
   * Adds a new node right after the head.
   * @private
   * @param {Object} node
   */
  _addNode(node) {
    node.prev = this.head;
    node.next = this.head.next;

    this.head.next.prev = node;
    this.head.next = node;
  }

  /**
   * Removes an existing node from the doubly linked list.
   * @private
   * @param {Object} node
   */
  _removeNode(node) {
    const prev = node.prev;
    const next = node.next;

    prev.next = next;
    next.prev = prev;
  }

  /**
   * Moves a node to the head (most recently used position).
   * @private
   * @param {Object} node
   */
  _moveToHead(node) {
    this._removeNode(node);
    this._addNode(node);
  }

  /**
   * Removes and returns the node right before the tail (least recently used).
   * @private
   * @return {Object}
   */
  _popTail() {
    const res = this.tail.prev;
    this._removeNode(res);
    return res;
  }
}

class LRUCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 0) {
      throw new RangeError("Capacity must be a non-negative integer");
    }

    this.capacity = capacity;
    this.cache = new Map();
  }

