    return this.cache.size;
  }

  has(key) {
    return this.cache.has(key);
  }

  clear() {
    this.cache.clear();
  }

  toString() {
    const entries = [...this.cache.entries()]
      .map(([k, v]) => `${k}:${v}`)
      .join(', ');
    return `LRUCache(${this.size}/${this.capacity}) { ${entries} }`;
  }
}

