) -> list[str]:
    """Parse a CSV string and return unique, normalized, valid emails."""
    if not isinstance(raw_csv, str):
        raise TypeError("raw_csv must be a string")

    is_valid = validator or _default_validator
    unique_emails: dict[str, None] = {}

    try:
        rows = csv.reader(io.StringIO(raw_csv, newline=""), skipinitialspace=True)
        for row in rows:
            for value in row:
                email = value.strip().casefold()
                if email and is_valid(email):
