    except csv.Error as exc:
        raise ValueError(f"Invalid CSV input: {exc}") from exc

    return list(unique_emails)


def _default_validator(email: str) -> bool:
    if len(email) > 254 or email.count("@") != 1:
        return False

    local_part, domain = email.rsplit("@", 1)
    if (
        not local_part
        or len(local_part) > 64
        or local_part.startswith(".")
        or local_part.endswith(".")
        or ".." in local_part
        or len(domain) > 253
    ):
        return False

    try:
        ascii_domain = domain.encode("idna").decode("ascii").casefold()
    except UnicodeError:
        return False

    normalized = f"{local_part}@{ascii_domain}"
    return len(normalized) <= 254 and _EMAIL_PATTERN.fullmatch(normalized) is not None

