function parseCsv(input) {
  const fields = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < input.length; i += 1) {
    const character = input[i];

    if (character === '"') {
      if (inQuotes && input[i + 1] === '"') {
        field += '"';
        i += 1;
      } else {
        inQuotes = !inQuotes;
      }
    } else if ((character === "," || character === "\n" || character === "\r") && !inQuotes) {
      fields.push(field);
      field = "";

      if (character === "\r" && input[i + 1] === "\n") {
        i += 1;
      }
    } else {
      field += character;
    }
  }

  fields.push(field);
  return fields;
}

